const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point(-119.02882425044682, 46.929987337866386);
  const point2 = ee.Geometry.Point(-119.70997639198902, 43.19114225407087);
  const targetDate = ee.Date('2015-11-29');
  const startDate = targetDate.advance(-1, 'day'); // +/- 1 day for flexibility
  const endDate = targetDate.advance(1, 'day');

  // Landsat 8 Surface Reflectance (Level 2, Collection 2, Tier 1)
  const collectionId = 'LANDSAT/LC08/C02/T1_L2';
  const QA_BAND = 'QA_PIXEL';

  // Function to get the closest image and check cloud status
  const checkCloudStatus = async (point, name) => {
    let images = ee.ImageCollection(collectionId)
      .filterBounds(point)
      .filterDate(startDate, endDate)
      .map(image => image.set('time_diff', (ee.Number(image.get('system:time_start')).subtract(targetDate.millis())).abs()));

    const numImages = await images.size().getInfo();
    if (numImages === 0) {
      console.log(`No images found for ${name} between ${startDate.format('YYYY-MM-dd').getInfo()} and ${endDate.format('YYYY-MM-dd').getInfo()}.`);
      return { status: 'C1', cloudy: null };
    }

    const image = await images.sort('time_diff').first();
    const acquisitionDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();

    // Get the QA_PIXEL value at the point
    const qa_pixel_value = await image.select(QA_BAND).reduceRegion({
      reducer: ee.Reducer.first(),
      geometry: point,
      scale: 30, // Landsat resolution
      maxPixels: 1e9
    }).get(QA_BAND).getInfo();

    if (qa_pixel_value === null || typeof qa_pixel_value !== 'number') {
      console.log(`Calculation failure for ${name}: QA_PIXEL value is null or invalid. Image Date: ${acquisitionDate}`);
      return { status: 'C3', cloudy: null };
    }

    // QA_PIXEL Bitmask for Landsat 8 (Collection 2, Tier 1, Level 2):
    // Bit 3: Cloud (0 = Not cloud, 1 = Cloud)
    // Bit 5: Cirrus (0 = Not cirrus, 1 = Cirrus)
    const CLOUD_BIT = (1 << 3); // Bit 3
    const CIRRUS_BIT = (1 << 5); // Bit 5

    const isCloudy = (qa_pixel_value & CLOUD_BIT) !== 0;
    const isCirrus = (qa_pixel_value & CIRRUS_BIT) !== 0;

    const coveredByCloudsOrFogs = isCloudy || isCirrus;

    console.log(`${name} (Date: ${acquisitionDate}): QA_PIXEL=${qa_pixel_value} (Cloud bit set: ${isCloudy}, Cirrus bit set: ${isCirrus}). Covered by clouds/fogs: ${coveredByCloudsOrFogs}`);
    return { status: 'OK', cloudy: coveredByCloudsOrFogs };
  };

  try {
    const result1 = await checkCloudStatus(point1, 'Location 1');
    if (result1.status !== 'OK') {
      console.log("C1");
      return;
    }

    const result2 = await checkCloudStatus(point2, 'Location 2');
    if (result2.status !== 'OK') {
      console.log("C1");
      return;
    }

    // Final Validation & Answer
    if (result1.cloudy === null || result2.cloudy === null) {
      console.log("C3"); // Should be caught earlier, but as a fallback
    } else if (result1.cloudy && result2.cloudy) {
      console.log("A"); // Both are cloudy
    } else {
      console.log("B"); // At least one is not cloudy
    }

  } catch (error) {
    console.error("An error occurred during analysis: ", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
